  'trade.giveAwayBody': { en: 'This copy leaves your collection now so your friend can add it by scanning the code.', es: 'Esta copia sale de tu colección ahora para que tu amigo la añada escaneando el código.', fr: 'Cet exemplaire quitte votre collection maintenant pour que votre ami puisse l’ajouter en scannant le code.', it: 'Questa copia lascia ora la tua collezione così il tuo amico può aggiungerla scansionando il codice.', pt: 'Esta cópia sai da sua coleção agora para que seu amigo a adicione escaneando o código.', de: 'Dieses Exemplar verlässt jetzt deine Sammlung, damit dein Freund es durch Scannen des Codes hinzufügen kann.' },
  'trade.giveAway': { en: 'Give away', es: 'Regalar', fr: 'Offrir', it: 'Regala', pt: 'Presentear', de: 'Verschenken' },

