  'room.trueScale': { en: 'Real-size scaling', es: 'Escalar a tamaño real', fr: 'Échelle réelle', it: 'Scala reale', pt: 'Escala real', de: 'Maßstabsgetreu' },
  'room.trueScaleBody': { en: 'Hang pieces at their true relative sizes (the largest fills the wall).', es: 'Cuelga las obras a su tamaño relativo real (la más grande llena la pared).', fr: 'Accroche les œuvres à leur taille relative réelle (la plus grande remplit le mur).', it: 'Appende le opere alle loro dimensioni relative reali (la più grande riempie la parete).', pt: 'Pendura as obras no seu tamanho relativo real (a maior preenche a parede).', de: 'Hängt Werke in ihren echten relativen Größen (das größte füllt die Wand).' },
  'set.units': { en: 'Show dimensions in inches', es: 'Mostrar dimensiones en pulgadas', fr: 'Afficher les dimensions en pouces', it: 'Mostra le dimensioni in pollici', pt: 'Mostrar dimensões em polegadas', de: 'Maße in Zoll anzeigen' },
  'set.unitsBody': { en: 'Off shows centimeters (cm), on shows inches (in).', es: 'Apagado muestra centímetros (cm), encendido muestra pulgadas (in).', fr: 'Désactivé : centimètres (cm) ; activé : pouces (in).', it: 'Off mostra centimetri (cm), on mostra pollici (in).', pt: 'Desligado mostra centímetros (cm), ligado mostra polegadas (in).', de: 'Aus zeigt Zentimeter (cm), an zeigt Zoll (in).' },
  'set.revealSoundsBody': { en: 'A chime when you discover a piece — grander the rarer it is.', es: 'Un tintineo al descubrir una pieza: más grandioso cuanto más rara.', fr: 'Un carillon quand vous découvrez une pièce — plus grandiose selon sa rareté.', it: 'Un suono quando scopri un’opera: più grandioso quanto più è rara.', pt: 'Um toque ao descobrir uma peça — mais grandioso quanto mais rara.', de: 'Ein Klang, wenn du ein Stück entdeckst — großartiger, je seltener es ist.' },
  'set.tapToPreview': { en: 'Tap to preview', es: 'Toca para escuchar', fr: 'Touchez pour écouter', it: 'Tocca per ascoltare', pt: 'Toque para ouvir', de: 'Zum Anhören tippen' },
  'set.vibration': { en: 'Vibration', es: 'Vibración', fr: 'Vibration', it: 'Vibrazione', pt: 'Vibração', de: 'Vibration' },
  'set.vibrationBody': { en: 'Haptic feedback when a piece is revealed.', es: 'Respuesta háptica al revelar una pieza.', fr: 'Retour haptique lors de la révélation d’une pièce.', it: 'Feedback aptico quando si rivela un’opera.', pt: 'Retorno tátil ao revelar uma peça.', de: 'Haptische Rückmeldung, wenn ein Stück enthüllt wird.' },
  'set.reduceMotion': { en: 'Reduce animations', es: 'Reducir animaciones', fr: 'Réduire les animations', it: 'Riduci le animazioni', pt: 'Reduzir animações', de: 'Animationen reduzieren' },
  'set.reduceMotionBody': { en: 'A calmer reveal — no rings, sparks or sweeps. Easier on the eyes and the battery.', es: 'Una revelación más tranquila: sin anillos, destellos ni barridos. Más suave para la vista y la batería.', fr: 'Une révélation plus calme — sans anneaux, étincelles ni balayages. Plus doux pour les yeux et la batterie.', it: 'Una rivelazione più tranquilla: niente anelli, scintille o effetti. Più riposante per occhi e batteria.', pt: 'Uma revelação mais calma — sem anéis, faíscas ou varreduras. Melhor para os olhos e a bateria.', de: 'Eine ruhigere Enthüllung — keine Ringe, Funken oder Schwenks. Schonender für Augen und Akku.' },
  'set.safety': { en: 'Safety', es: 'Seguridad', fr: 'Sécurité', it: 'Sicurezza', pt: 'Segurança', de: 'Sicherheit' },
  'set.safetyTitle': { en: 'How scanning stays safe', es: 'Cómo el escaneo se mantiene seguro', fr: 'Comment le scan reste sûr', it: 'Come la scansione resta sicura', pt: 'Como a leitura permanece segura', de: 'Wie das Scannen sicher bleibt' },
  'set.safetyBody': { en: "QArt never opens a code's link — it only reinterprets it.", es: 'QArt nunca abre el enlace de un código: solo lo reinterpreta.', fr: "QArt n'ouvre jamais le lien d'un code — il le réinterprète seulement.", it: 'QArt non apre mai il link di un codice: lo reinterpreta soltanto.', pt: 'O QArt nunca abre o link de um código — apenas o reinterpreta.', de: 'QArt öffnet nie den Link eines Codes — es deutet ihn nur um.' },
  'set.learn': { en: 'Learn', es: 'Aprende', fr: 'Apprendre', it: 'Impara', pt: 'Aprenda', de: 'Lernen' },
  'set.howToPlay': { en: 'How to play', es: 'Cómo jugar', fr: 'Comment jouer', it: 'Come si gioca', pt: 'Como jogar', de: 'Spielanleitung' },
  'set.howToPlayBody': { en: 'Scanning, rarities, cooldowns, special codes and the gift shop.', es: 'Escaneo, rarezas, esperas, códigos especiales y la tienda.', fr: 'Le scan, les raretés, les délais, les codes spéciaux et la boutique.', it: 'Scansione, rarità, attese, codici speciali e la bottega.', pt: 'Leitura, raridades, esperas, códigos especiais e a loja.', de: 'Scannen, Seltenheiten, Wartezeiten, Sondercodes und der Shop.' },
