  'set.artistsDiscovered': { en: 'Artists discovered', es: 'Artistas descubiertos', fr: 'Artistes découverts', it: 'Artisti scoperti', pt: 'Artistas descobertos', de: 'Entdeckte Künstler' },
  'set.totalScans': { en: 'Total scans', es: 'Escaneos totales', fr: 'Total des scans', it: 'Scansioni totali', pt: 'Total de leituras', de: 'Scans insgesamt' },
  'set.privacy': { en: 'Privacy', es: 'Privacidad', fr: 'Confidentialité', it: 'Privacy', pt: 'Privacidade', de: 'Datenschutz' },
  'set.analytics': { en: 'Share anonymous analytics', es: 'Compartir análisis anónimos', fr: 'Partager des analyses anonymes', it: 'Condividi statistiche anonime', pt: 'Compartilhar dados anônimos', de: 'Anonyme Analysen teilen' },
  'set.analyticsBody': { en: 'Helps improve QArt and plan new collections. No accounts, no personal data — just anonymous, aggregate usage.', es: 'Ayuda a mejorar QArt y planear nuevas colecciones. Sin cuentas ni datos personales: solo uso anónimo y agregado.', fr: 'Aide à améliorer QArt et à planifier de nouvelles collections. Pas de comptes, pas de données personnelles — seulement un usage anonyme et agrégé.', it: 'Aiuta a migliorare QArt e a pianificare nuove collezioni. Nessun account, nessun dato personale: solo uso anonimo e aggregato.', pt: 'Ajuda a melhorar o QArt e planejar novas coleções. Sem contas nem dados pessoais — apenas uso anônimo e agregado.', de: 'Hilft, QArt zu verbessern und neue Sammlungen zu planen. Keine Konten, keine persönlichen Daten — nur anonyme, aggregierte Nutzung.' },
  'set.support': { en: 'Support', es: 'Apoyo', fr: 'Soutien', it: 'Sostieni', pt: 'Apoio', de: 'Unterstützung' },
  'set.supportTitle': { en: 'Support QArt', es: 'Apoya QArt', fr: 'Soutenir QArt', it: 'Sostieni QArt', pt: 'Apoie o QArt', de: 'QArt unterstützen' },
  'set.supportBody': { en: 'QArt is free, ad-free and has no paid currency. A donation helps keep it going — never required.', es: 'QArt es gratis, sin anuncios y sin moneda de pago. Una donación ayuda a mantenerlo, nunca es obligatoria.', fr: 'QArt est gratuit, sans publicité et sans monnaie payante. Un don aide à le faire vivre — jamais obligatoire.', it: 'QArt è gratuito, senza pubblicità e senza valuta a pagamento. Una donazione aiuta a mandarlo avanti, mai obbligatoria.', pt: 'O QArt é gratuito, sem anúncios e sem moeda paga. Uma doação ajuda a mantê-lo — nunca obrigatória.', de: 'QArt ist kostenlos, werbefrei und hat keine Bezahlwährung. Eine Spende hilft, es am Laufen zu halten — nie erforderlich.' },
  'set.shareTitle': { en: 'Share QArt', es: 'Comparte QArt', fr: 'Partager QArt', it: 'Condividi QArt', pt: 'Compartilhar o QArt', de: 'QArt teilen' },
  'set.rateApp': { en: 'Rate the app', es: 'Califica la app', fr: 'Noter l’app', it: 'Valuta l’app', pt: 'Avaliar o app', de: 'App bewerten' },
  'set.contact': { en: 'Contact', es: 'Contacto', fr: 'Contact', it: 'Contatti', pt: 'Contato', de: 'Kontakt' },
