  'set.contactBody': { en: "Questions, bugs or ideas? We'd love to hear from you.", es: '¿Preguntas, errores o ideas? Nos encantaría saber de ti.', fr: 'Questions, bugs ou idées ? Nous serions ravis de vous lire.', it: 'Domande, bug o idee? Ci farebbe piacere sentirti.', pt: 'Perguntas, erros ou ideias? Adoraríamos ouvir você.', de: 'Fragen, Fehler oder Ideen? Wir freuen uns, von dir zu hören.' },
  'set.about': { en: 'About', es: 'Acerca de', fr: 'À propos', it: 'Informazioni', pt: 'Sobre', de: 'Über' },
