  'set.limitScans': { en: 'Limit to {n} scans per day', es: 'Limitar a {n} escaneos por día', fr: 'Limiter à {n} scans par jour', it: 'Limita a {n} scansioni al giorno', pt: 'Limitar a {n} leituras por dia', de: 'Auf {n} Scans pro Tag begrenzen' },
  'set.limitScansBody': { en: 'Turn off to test scanning freely.', es: 'Desactiva para probar el escaneo sin límite.', fr: 'Désactivez pour tester le scan librement.', it: 'Disattiva per testare la scansione liberamente.', pt: 'Desligue para testar a leitura livremente.', de: 'Ausschalten, um frei zu testen.' },
  'set.cooldownTitle': { en: 'Escalating cooldown per code', es: 'Espera creciente por código', fr: 'Délai croissant par code', it: 'Attesa crescente per codice', pt: 'Espera crescente por código', de: 'Steigende Wartezeit pro Code' },
  'set.cooldownBody': { en: 'Turn off to re-scan the same code freely.', es: 'Desactiva para reescanear el mismo código sin límite.', fr: 'Désactivez pour rescanner le même code librement.', it: 'Disattiva per riscansionare lo stesso codice liberamente.', pt: 'Desligue para reler o mesmo código livremente.', de: 'Ausschalten, um denselben Code frei erneut zu scannen.' },
