  'set.grantShards': { en: 'Grant +1000 shards', es: 'Otorgar +1000 fragmentos', fr: 'Accorder +1000 éclats', it: 'Concedi +1000 frammenti', pt: 'Conceder +1000 fragmentos', de: '+1000 Splitter gewähren' },
