  'set.resetTitle': { en: 'Reset all data', es: 'Borrar todos los datos', fr: 'Réinitialiser toutes les données', it: 'Reimposta tutti i dati', pt: 'Apagar todos os dados', de: 'Alle Daten zurücksetzen' },
  'set.resetConfirmTitle': { en: 'Reset all data?', es: '¿Borrar todos los datos?', fr: 'Réinitialiser toutes les données ?', it: 'Reimpostare tutti i dati?', pt: 'Apagar todos os dados?', de: 'Alle Daten zurücksetzen?' },
  'set.resetConfirmBody': { en: 'This clears your entire collection, shards and stats. This cannot be undone.', es: 'Esto borra toda tu colección, fragmentos y estadísticas. No se puede deshacer.', fr: 'Cela efface toute votre collection, vos éclats et vos statistiques. Irréversible.', it: 'Questo cancella tutta la tua collezione, i frammenti e le statistiche. Non è reversibile.', pt: 'Isso apaga toda a sua coleção, fragmentos e estatísticas. Não pode ser desfeito.', de: 'Dies löscht deine gesamte Sammlung, Splitter und Statistiken. Kann nicht rückgängig gemacht werden.' },
