  'set.shareMessage': { en: 'QArt — collect public-domain masterpieces by scanning any QR code. {url}', es: 'QArt: colecciona obras maestras de dominio público escaneando cualquier código QR. {url}', fr: 'QArt — collectionnez des chefs-d’œuvre du domaine public en scannant n’importe quel QR code. {url}', it: 'QArt: colleziona capolavori di pubblico dominio scansionando qualsiasi QR code. {url}', pt: 'QArt — colecione obras-primas de domínio público escaneando qualquer QR code. {url}', de: 'QArt — sammle gemeinfreie Meisterwerke, indem du einen beliebigen QR-Code scannst. {url}' },
