  'disc.worksInStyle': { en: '{n} work{s} in this style · {m} collected', es: '{n} obra{s} en este estilo · {m} coleccionadas', fr: '{n} œuvre{s} dans ce style · {m} collectionnées', it: '{n} opera{e} in questo stile · {m} collezionate', pt: '{n} obra{s} neste estilo · {m} coletadas', de: '{n} Werk{e} in diesem Stil · {m} gesammelt' },
  'disc.curio1': { en: 'The catalog holds {n} paintings across {c} collections.', es: 'El catálogo reúne {n} cuadros en {c} colecciones.', fr: 'Le catalogue réunit {n} tableaux répartis en {c} collections.', it: 'Il catalogo raccoglie {n} quadri in {c} collezioni.', pt: 'O catálogo reúne {n} quadros em {c} coleções.', de: 'Der Katalog umfasst {n} Bilder in {c} Sammlungen.' },
  'disc.curio2': { en: 'Only {n} pieces sit at the very top of the rarity ladder.', es: 'Solo {n} piezas están en la cima de la escala de rareza.', fr: 'Seules {n} pièces trônent au sommet de l’échelle de rareté.', it: 'Solo {n} opere stanno in cima alla scala della rarità.', pt: 'Apenas {n} peças estão no topo da escala de raridade.', de: 'Nur {n} Stücke stehen ganz oben auf der Seltenheitsleiter.' },
  'disc.curio3': { en: 'Every QR in the world maps to exactly one artwork — the same code always reveals the same piece.', es: 'Cada QR del mundo corresponde a exactamente una obra: el mismo código revela siempre la misma pieza.', fr: 'Chaque QR du monde correspond à une seule œuvre — le même code révèle toujours la même pièce.', it: 'Ogni QR al mondo corrisponde a una sola opera: lo stesso codice svela sempre la stessa opera.', pt: 'Cada QR do mundo corresponde a exatamente uma obra — o mesmo código revela sempre a mesma peça.', de: 'Jeder QR-Code der Welt entspricht genau einem Werk — derselbe Code enthüllt immer dasselbe Stück.' },
  'disc.curio4': { en: '{n} artists are waiting to be discovered.', es: '{n} artistas esperan a ser descubiertos.', fr: '{n} artistes attendent d’être découverts.', it: '{n} artisti aspettano di essere scoperti.', pt: '{n} artistas esperam ser descobertos.', de: '{n} Künstler warten darauf, entdeckt zu werden.' },
  'disc.curio5': { en: 'Some works are split into fragments — collect every part to assemble the whole.', es: 'Algunas obras se dividen en fragmentos: reúne cada parte para armar el conjunto.', fr: 'Certaines œuvres sont divisées en fragments — réunissez chaque partie pour reconstituer l’ensemble.', it: 'Alcune opere sono divise in frammenti: raccogli ogni parte per comporre l’insieme.', pt: 'Algumas obras são divididas em fragmentos — reúna cada parte para montar o todo.', de: 'Manche Werke sind in Fragmente geteilt — sammle jedes Teil, um das Ganze zusammenzusetzen.' },

  // ---- Safety screen ----
  'safety.title': { en: 'Scan safely', es: 'Escanea con seguridad', fr: 'Scanner en toute sécurité', it: 'Scansiona in sicurezza', pt: 'Escaneie com segurança', de: 'Sicher scannen' },
  'safety.subtitle': { en: 'QArt turns QR codes into art — without any of the usual risk.', es: 'QArt convierte códigos QR en arte, sin ninguno de los riesgos habituales.', fr: "QArt transforme les QR codes en art — sans aucun des risques habituels.", it: 'QArt trasforma i QR code in arte, senza alcuno dei soliti rischi.', pt: 'O QArt transforma QR codes em arte — sem nenhum dos riscos habituais.', de: 'QArt verwandelt QR-Codes in Kunst — ohne die üblichen Risiken.' },
  'safety.p1t': { en: 'Links are never opened', es: 'Los enlaces nunca se abren', fr: 'Les liens ne sont jamais ouverts', it: 'I link non vengono mai aperti', pt: 'Os links nunca são abertos', de: 'Links werden nie geöffnet' },
  'safety.p1b': { en: 'QArt does not visit the website or content a QR code points to. Ever.', es: 'QArt no visita el sitio ni el contenido al que apunta un código QR. Nunca.', fr: "QArt ne visite jamais le site ou le contenu vers lequel pointe un QR code.", it: 'QArt non visita mai il sito o il contenuto a cui punta un QR code.', pt: 'O QArt não visita o site nem o conteúdo para o qual um QR code aponta. Nunca.', de: 'QArt besucht nie die Website oder den Inhalt, auf den ein QR-Code verweist. Niemals.' },
  'safety.p2t': { en: 'It only reinterprets the code', es: 'Solo reinterpreta el código', fr: 'Il ne fait que réinterpréter le code', it: 'Reinterpreta soltanto il codice', pt: 'Ele apenas reinterpreta o código', de: 'Es deutet den Code nur um' },
  'safety.p2b': { en: "The code's raw text is read and transformed into an artwork for your collection — nothing else happens with it.", es: 'El texto del código se lee y se transforma en una obra para tu colección; no ocurre nada más con él.', fr: "Le texte brut du code est lu et transformé en une œuvre pour votre collection — rien d'autre n'en est fait.", it: 'Il testo grezzo del codice viene letto e trasformato in un’opera per la tua collezione: nient’altro.', pt: 'O texto do código é lido e transformado numa obra para a sua coleção — nada mais acontece com ele.', de: 'Der reine Text des Codes wird gelesen und in ein Werk für deine Sammlung verwandelt — sonst geschieht nichts damit.' },
  'safety.p3t': { en: 'Unknown codes are completely safe', es: 'Los códigos desconocidos son totalmente seguros', fr: 'Les codes inconnus sont parfaitement sûrs', it: 'I codici sconosciuti sono del tutto sicuri', pt: 'Códigos desconhecidos são totalmente seguros', de: 'Unbekannte Codes sind völlig sicher' },
  'safety.p3b': { en: "Even a code from a stranger can't harm your phone here. At worst, it's just a surprise piece of art.", es: 'Incluso un código de un desconocido no puede dañar tu teléfono aquí. En el peor caso, es solo una obra sorpresa.', fr: "Même le code d'un inconnu ne peut pas nuire à votre téléphone ici. Au pire, c'est juste une œuvre surprise.", it: 'Anche il codice di uno sconosciuto non può danneggiare il tuo telefono qui. Al peggio, è solo un’opera a sorpresa.', pt: 'Mesmo um código de um estranho não pode danificar seu telefone aqui. No pior caso, é apenas uma obra surpresa.', de: 'Selbst der Code eines Fremden kann deinem Telefon hier nicht schaden. Schlimmstenfalls ist es nur ein überraschendes Kunstwerk.' },
  'safety.p4t': { en: 'Mind your surroundings', es: 'Atento a tu entorno', fr: 'Attention à votre environnement', it: 'Fai attenzione a ciò che ti circonda', pt: 'Atenção ao seu redor', de: 'Achte auf deine Umgebung' },
  'safety.p4b': { en: "Hunting takes you out into the world. Stay aware of what's around you, watch your step, and don't scan anywhere unsafe.", es: 'La caza te lleva al mundo real. Mantente atento a lo que te rodea, mira por dónde pisas y no escanees en lugares peligrosos.', fr: "La chasse vous emmène dans le monde réel. Restez attentif à ce qui vous entoure, regardez où vous marchez et ne scannez pas dans un endroit dangereux.", it: 'La caccia ti porta nel mondo reale. Fai attenzione a ciò che ti circonda, guarda dove metti i piedi e non scansionare in luoghi pericolosi.', pt: 'A caça leva você ao mundo real. Fique atento ao que está à sua volta, olhe por onde anda e não escaneie em lugares perigosos.', de: 'Die Jagd führt dich hinaus in die Welt. Bleibe wachsam gegenüber deiner Umgebung, achte auf deine Schritte und scanne nicht an unsicheren Orten.' },
  'safety.gotIt': { en: 'Got it', es: 'Entendido', fr: 'Compris', it: 'Ho capito', pt: 'Entendi', de: 'Verstanden' },
  'safety.iUnderstand': { en: 'I understand', es: 'Lo entiendo', fr: 'Je comprends', it: 'Ho capito', pt: 'Eu entendo', de: 'Ich verstehe' },

