  'reveal.h2': { en: 'A fine find', es: 'Un buen hallazgo', fr: 'Une belle trouvaille', it: 'Un bel ritrovamento', pt: 'Um belo achado', de: 'Ein schöner Fund' },
  'reveal.h3': { en: 'A remarkable find', es: 'Un hallazgo notable', fr: 'Une trouvaille remarquable', it: 'Un ritrovamento notevole', pt: 'Um achado notável', de: 'Ein bemerkenswerter Fund' },
  'reveal.h4': { en: 'An extraordinary find', es: 'Un hallazgo extraordinario', fr: 'Une trouvaille extraordinaire', it: 'Un ritrovamento straordinario', pt: 'Um achado extraordinário', de: 'Ein außergewöhnlicher Fund' },
  'reveal.h5': { en: 'A once-in-a-lifetime find', es: 'Un hallazgo único en la vida', fr: "Une trouvaille unique dans une vie", it: 'Un ritrovamento unico nella vita', pt: 'Um achado único na vida', de: 'Ein Fund fürs Leben' },
  'reveal.anotherCopy': { en: 'Another copy — you now hold {count}', es: 'Otra copia: ahora tienes {count}', fr: 'Un autre exemplaire — vous en avez {count}', it: "Un'altra copia: ora ne hai {count}", pt: 'Outra cópia — agora você tem {count}', de: 'Noch ein Exemplar — du hast jetzt {count}' },
  'reveal.finalPart': { en: 'Final part — the work is assembled!', es: 'Última parte: ¡la obra está completa!', fr: "Dernière partie — l'œuvre est assemblée !", it: "Ultima parte: l'opera è completa!", pt: 'Última parte — a obra está montada!', de: 'Letztes Teil — das Werk ist vollständig!' },
  'reveal.partOf': { en: 'Part {index} of {total} · {have}/{total} collected', es: 'Parte {index} de {total} · {have}/{total} reunidas', fr: 'Partie {index} sur {total} · {have}/{total} réunies', it: 'Parte {index} di {total} · {have}/{total} raccolte', pt: 'Parte {index} de {total} · {have}/{total} reunidas', de: 'Teil {index} von {total} · {have}/{total} gesammelt' },
