  // ---- Viewer ----
  'viewer.photosTitle': { en: 'Photos access needed', es: 'Se necesita acceso a Fotos', fr: "Accès aux photos requis", it: 'Serve l’accesso alle foto', pt: 'Acesso às fotos necessário', de: 'Fotozugriff erforderlich' },
  'viewer.photosBody': { en: 'Allow QArt to add photos so it can save this artwork. You can turn it on in Settings › QArt › Photos.', es: 'Permite que QArt añada fotos para guardar esta obra. Puedes activarlo en Ajustes › QArt › Fotos.', fr: "Autorisez QArt à ajouter des photos pour enregistrer cette œuvre. Activez-le dans Réglages › QArt › Photos.", it: 'Consenti a QArt di aggiungere foto per salvare quest’opera. Puoi attivarlo in Impostazioni › QArt › Foto.', pt: 'Permita que o QArt adicione fotos para salvar esta obra. Você pode ativar em Ajustes › QArt › Fotos.', de: 'Erlaube QArt, Fotos hinzuzufügen, um dieses Werk zu speichern. Du kannst es in Einstellungen › QArt › Fotos aktivieren.' },
  'viewer.couldNotSave': { en: 'Could not save', es: 'No se pudo guardar', fr: "Enregistrement impossible", it: 'Impossibile salvare', pt: 'Não foi possível salvar', de: 'Konnte nicht gespeichert werden' },
  'viewer.saveError': { en: 'Something went wrong while saving the image.', es: 'Algo salió mal al guardar la imagen.', fr: "Une erreur s'est produite lors de l'enregistrement de l'image.", it: 'Qualcosa è andato storto durante il salvataggio dell’immagine.', pt: 'Algo deu errado ao salvar a imagem.', de: 'Beim Speichern des Bildes ist etwas schiefgelaufen.' },
  'viewer.partsCollected': { en: '{have}/{total} parts collected · find the rest to complete it', es: '{have}/{total} partes reunidas · encuentra el resto para completarla', fr: '{have}/{total} parties réunies · trouvez le reste pour la compléter', it: '{have}/{total} parti raccolte · trova il resto per completarla', pt: '{have}/{total} partes reunidas · encontre o resto para completá-la', de: '{have}/{total} Teile gesammelt · finde den Rest, um es zu vervollständigen' },
  'viewer.saving': { en: 'Saving…', es: 'Guardando…', fr: 'Enregistrement…', it: 'Salvataggio…', pt: 'Salvando…', de: 'Wird gespeichert…' },
  'viewer.saved': { en: 'Saved to your photos', es: 'Guardado en tus fotos', fr: 'Enregistré dans vos photos', it: 'Salvato nelle tue foto', pt: 'Salvo nas suas fotos', de: 'In deinen Fotos gespeichert' },
  'viewer.saveToPhone': { en: 'Save to my phone', es: 'Guardar en mi teléfono', fr: 'Enregistrer sur mon téléphone', it: 'Salva sul telefono', pt: 'Salvar no meu telefone', de: 'Auf meinem Telefon speichern' },
